package com.casetracker.ui.law

val LF3_ACCIDENT_WORK_STANDARD: LawBook = LawBook(
    id = "accident_work_standard",
    name = "道路交通事故处理工作规范",
    articlesCount = 131,
    chapters = 13,
    intro = """公交管〔2018〕，自2018年5月1日施行，配套《道路交通事故处理程序规定》（公安部令第146号）使用，是事故处理岗位操作规范，全文收录（共131条）。""",
    articles = listOf(
        LawArticle("第一条", "", """为规范道路交通事故处理工作，保障公安机关交通管理部门及其交通警察依法公正处理道路交通事故，提高办案质量和效率，保护当事人的合法权益，根据《中华人民共和国道路交通安全法》《中华人民共和国道路交通安全法实施条例》《道路交通事故处理程序规定》等法律、行政法规、规章，制定本规范。"""),
        LawArticle("第二条", "", """公安机关交通管理部门及其交通警察处理道路交通事故应当以事实为根据，以法律为准绳，遵循合法、公正、公开、便民、效率的原则，尊重和保障人权，保护公民的人格尊严。公安机关交通管理部门及其交通警察应当遵循事故处理与事故预防相结合的原则，按照规定及时开展事故深度调查，加强事故统计分析和事故预防对策研究。"""),
        LawArticle("第三条", "", """交通警察在处理道路交通事故时应当按照规定使用规范用语。"""),
        LawArticle("第四条", "", """公安机关交通管理部门办理道路交通事故案件实行分级负责、专人办案、领导审批制度。对造成人员死亡或者其他疑难、复杂案件应当集体研究决定。"""),
        LawArticle("第五条", "", """县级以上公安机关交通管理部门应当按照道路交通事故处理岗位正规化建设要求，配置必需的人员、装备和办公场所。"""),
        LawArticle("第六条", "", """公安机关交通管理部门应当加强道路交通事故现场安全防护工作，提高交通警察安全防护意识和防护能力，加大安全防护投入，配备性能优良、操作简便的安全防护装备和设施，组织开展安全防护培训和实战演练。"""),
        LawArticle("第七条", "", """公安机关交通管理部门应当加强道路交通事故处理队伍专业化建设和人才培养，设区的市级以上公安机关交通管理部门应当建立道路交通事故处理人才库，聘请专业人员组建专家组。"""),
        LawArticle("第八条", "", """交通警察经过培训并考试合格，可以处理适用简易程序的道路交通事故。取得初级资格的交通警察，可以处理除死亡事故以外的道路交通事故，并可以协助取得中级以上资格的交通警察处理死亡事故。取得中级以上资格的交通警察，可以处理所有道路交通事故，并可以对道路交通事故案件进行复核。取得高级资格的交通警察，可以对取得初级、中级资格的交通警察处理道路交通事故进行指导。设区的市、县级公安机关交通管理部门分管事故处理工作的领导和事故处理机构负责人，应当取得中级以上资格。省级公安机关交通管理部门负责组织道路交通事故处理资格等级培训考试，对经培训并考试合格的交通警察核发道路交通事故处理资格等级证书。"""),
        LawArticle("第九条", "", """交通警察执勤巡逻时，警车应当配备警示标志、现场标划用具、执法记录设备等对道路交通事故现场进行先期处置的必需装备，以及适用简易程序处理道路交通事故的法律文书等。"""),
        LawArticle("第十条", "", """各级公安机关交通管理部门应当制定道路交通事故处理及追逃办案经费预算，保障所需经费。"""),
        LawArticle("第十一条", "", """各级公安机关交通管理部门应当制定群死群伤道路交通事故应急处置、载运危险物品车辆道路交通事故应急处置、校车道路交通事故应急处置、隧道道路交通事故应急处置、恶劣天气条件下道路交通事故应急处置以及自然灾害造成事故应急处置和交通肇事逃逸案件查缉等预案，并与相邻省、设区的市、县级公安机关交通管理部门建立协作、查缉机制。"""),
        LawArticle("第十二条", "", """警务辅助人员可以在交通警察的指导或监督下承担以下辅助工作：（一）协助接受道路交通事故报警；（二）维护事故现场秩序；（三）协助勘查事故现场；（四）保护和清理事故现场；（五）为当事人自行协商处理财产损失事故提供指导或协助；（六）协助监控、看管违法犯罪嫌疑人和交通肇事人；（七）查询、核对、采集和录入道路交通事故信息资料；（八）管理道路交通事故案卷文书、档案；（九）其他非执法工作。"""),
        LawArticle("第十三条", "", """设区的市、县级公安机关交通管理部门事故处理机构实行二十四小时值班备勤制度，根据辖区道路交通事故情况确定值班备勤人数，值班备勤民警不得少于二人。"""),
        LawArticle("第十四条", "", """交通警察巡逻发现道路交通事故，除符合自行协商条件或者可以适用简易程序处理的，应当立即报告本级公安机关交通管理部门指挥中心或者值班室，并先期处置事故现场。"""),
        LawArticle("第十五条", "", """指挥中心接到道路交通事故报警的，应当按照《道路交通事故处理程序规定》第十六条规定的内容进行询问并作记录，制作《受案登记表》。需要派员到现场处置的，指派就近执勤的交通警察立即赶赴现场进行先期处置，并根据情况进行以下处理：（一）需要适用一般程序处理的，通知事故处理民警赶赴现场，并调派支援警力赶赴现场维护交通安全和交通秩序；（二）需要现场救援的，立即通知相关单位救援人员、车辆赶赴现场；（三）属于上报范围的，立即报告上一级公安机关交通管理部门，并通过本级公安机关报告当地人民政府；（四）需要堵截、查缉交通肇事逃逸车辆的，通知相关路段执勤民警堵截或查缉过往车辆，通报相邻的公安机关交通管理部门布控、协查；（五）载运危险物品车辆发生事故的，立即通过本级公安机关报告当地人民政府，通报有关部门及时赶赴事故现场；（六）营运车辆、校车发生人员死亡事故的，通知当地人民政府有关行政管理部门；（七）造成道路、供电、供水、燃气、通讯等设施损毁的，通报有关部门及时处理。"""),
        LawArticle("第十六条", "", """指挥中心处置道路交通事故警情时，应当记录下列内容：（一）处警指令发出的时间；（二）接受处警指令的人员姓名；（三）处警指令的内容；（四）通知联动单位的时间；（五）向单位领导或上级部门报告的时间、方式以及批示和指示情况；（六）处警人员到达现场以及现场处置结束后，向指挥中心报告的时间及内容。"""),
        LawArticle("第十七条", "", """交通警察接到处警指令后，白天应当在五分钟内出警，夜间应当在十分钟内出警。"""),
        LawArticle("第十八条", "", """交通警察到达事故现场后，应当及时向指挥中心报告到达时间和事故发生地点、事故形态、车辆类型、乘载人员、道路通行、初查后果等现场简要情况，需要增加救援人员或者装备的，一并报告。"""),
        LawArticle("第十九条", "", """发生道路交通事故有以下情形的，公安机关交通管理部门应当立即通过本级公安机关报告当地人民政府，并逐级上报省级公安机关交通管理部门：（一）一次死亡三人以上的；（二）接送学生、幼儿车辆发生事故造成学生、幼儿受伤的；（三）高速公路上发生单起或者连续发生多起事故涉及五辆以上机动车的；（四）伤人事故涉及现役军人、公安民警或者军车、警车的；（五）造成外国人、港澳台人员受伤的；（六）省级公安机关交通管理部门要求上报的其他情形。"""),
        LawArticle("第二十条", "", """发生道路交通事故有以下情形的，公安机关交通管理部门应当立即通过本级公安机关报告当地人民政府，并逐级上报公安部交通管理局：（一）一次死亡五人以上的；（二）载运危险物品的车辆发生泄漏、爆炸、燃烧的；（三）发生大中型客车翻车、坠车、燃烧的；（四）接送学生、幼儿车辆发生事故造成学生、幼儿死亡或者五人以上受伤的；（五）高速公路上发生单起或者连续发生多起事故涉及十辆以上机动车，或者造成单向或双向交通中断的；（六）死亡事故涉及现役军人、公安民警或者军车、警车的；（七）造成外国人、港澳台人员死亡或者三人以上重伤的；（八）应当上报的其他情形。"""),
        LawArticle("第二十一条", "", """具有本规范第十九条和第二十条第五项至第八项规定情形的，设区的市公安机关交通管理部门负责人应当立即赶赴事故现场。具有本规范第二十条第一项至第四项规定情形的，省级公安机关交通管理部门应当派人赶赴事故现场。发生一次死亡十人以上或者其他重大敏感的道路交通事故，公安部交通管理局应当派人赶赴事故现场。"""),
        LawArticle("第二十二条", "", """发生道路交通事故后当事人未报警，在事故现场撤除后，当事人又报警请求公安机关交通管理部门处理的，公安机关交通管理部门应当按照《道路交通事故处理程序规定》第十六条规定的记录内容予以记录，并在三日内根据当事人提供的证据或案件线索进行核查。经核查道路交通事故事实存在的，应当受理，制作《受案登记表》；经核查无法证明道路交通事故事实存在或者不属于管辖的，应当制作《不予受理告知书》。"""),
        LawArticle("第二十三条", "", """公安机关交通管理部门接到当事人报警，符合自行协商条件的，可以通过电话、微信、短信等方式引导当事人在确保安全的原则下，固定证据后将车辆就近移至不妨碍交通的地点，再协商处理损害赔偿事宜，并可以指导当事人通过互联网在线快速处理等方式自行协商。"""),
        LawArticle("第二十四条", "", """交通警察或者警务辅助人员执勤中发现的道路交通事故属于互联网在线快速处理范围的，可以指导或协助当事人通过互联网在线自行协商处理。"""),
        LawArticle("第二十五条", "", """交通警察到达现场后，事故车辆可以移动的，交通警察对现场拍照或者采用其他方式固定现场证据后，应当责令当事人立即撤离现场，将车辆就近移至不妨碍交通的地点。拒不撤离的，予以强制撤离。"""),
        LawArticle("第二十六条", "", """撤离现场后，交通警察应当根据固定的现场证据和当事人陈述、证人证言，认定道路交通事故事实，确定当事人的责任，填写《道路交通事故认定书（简易程序）》，由当事人签名，并当场送达当事人。不具备当场制作条件的，交通警察应当在三日内制作并送达。"""),
        LawArticle("第二十七条", "", """当事人共同请求调解的，交通警察应当当场进行调解，并在《道路交通事故认定书（简易程序）》上记录调解结果，由当事人签名，送达当事人。"""),
        LawArticle("第二十八条", "", """当事人对道路交通事故认定有异议，或者拒绝在《道路交通事故认定书（简易程序）》上签名，或者不同意调解的，交通警察应当在该认定书上予以记录，送达当事人。"""),
        LawArticle("第二十九条", "", """当事人伤势轻微，各方当事人一致同意适用简易程序处理的，交通警察应当在《道路交通事故认定书（简易程序）》上予以记录，并由各方当事人签名。"""),
        LawArticle("第三十条", "", """适用简易程序处理道路交通事故，当事人为无民事行为能力人或者限制民事行为能力人的，应当通知其监护人或者近亲属到场，并在认定书上记录其身份信息。"""),
        LawArticle("第三十一条", "", """交通警察到达事故现场后，应当按照《道路交通事故处理程序规定》及有关标准和规范的要求，严格落实安全防护措施。"""),
        LawArticle("第三十二条", "", """交通警察赶赴现场处理道路交通事故，应当按照规定穿着现场防护服或者专门的现场勘查服，夜间佩戴发光或者反光器具，配备必要警用装备，携带道路交通事故现场勘查器材和现场防护装备。"""),
        LawArticle("第三十三条", "", """交通警察到达现场后，应当根据现场情况利用警戒带、锥筒等划出警戒区，白天在距离现场来车方向五十米至一百五十米外或者路口处放置发光或者反光锥筒和警告标志，夜间或特殊气象条件下应当增加发光或反光锥筒，延长警示距离。高速公路应当停放警车示警，白天在距离现场来车方向二百米外，夜间或特殊气象条件下在五百米至一千米外设置警告标志和减（限）速标志。"""),
        LawArticle("第三十四条", "", """最先到达现场的警车应当停放在距事故现场来车方向一百米以外，并开启警灯、危险报警闪光灯，待现场安全防护设置完成后再根据现场指挥停放在安全和便于抢救、勘查的位置。"""),
        LawArticle("第三十五条", "", """道路交通事故涉及爆炸性、易燃性、毒害性、放射性、腐蚀性、传染病病原体等危险物品的，公安机关交通管理部门应当协同有关部门划定隔离区，封闭道路、疏散过往车辆、人员，禁止无关人员、车辆进入，待险情消除后方可勘查现场。"""),
        LawArticle("第三十六条", "", """因道路交通事故导致交通中断或者现场处置、勘查需要采取封闭道路等交通管制措施的，交通警察应当报告指挥中心，由指挥中心通知相关路段执勤民警提前组织分流，并通过可变信息标志、绕行提示标志以及电台广播、互联网发布等方式提醒其他车辆绕行。"""),
        LawArticle("第三十七条", "", """交通警察应当在道路交通事故现场勘查完毕后二十四小时内，将有关信息录入公安交通管理综合应用平台，并及时补充完善。"""),
        LawArticle("第三十八条", "", """交通警察调查道路交通事故时，应当合法、及时、客观、全面地收集证据。办理涉嫌交通肇事或者危险驾驶犯罪案件侦查终结的，应当全面审查证明证据收集合法性的证据材料，依法排除非法证据。"""),
        LawArticle("第三十九条", "", """交通警察调查道路交通事故时，需要见证的，应当邀请与案件无关的公民作为见证人。"""),
        LawArticle("第四十条", "", """公安机关交通管理部门在调查道路交通事故过程中，发现当事人涉嫌交通肇事或者危险驾驶犯罪的，应当依法立案侦查。发现当事人有其他违法犯罪嫌疑的，应当及时移送公安机关有关部门。"""),
        LawArticle("第四十一条", "", """交通警察到达现场后，发现有人员受伤的，应当立即组织施救。因抢救伤员需要变动现场的，应当标明或者记录需要变动的现场元素，并通过拍照或者摄像记录伤员在现场的原始位置及状态。"""),
        LawArticle("第四十二条", "", """交通警察到达现场后，应当紧急疏散现场人员、车辆，对进入警戒区的无关人员责令其立即离开，必要时可予以带离。遇有无关人员对事故现场以及受伤人员和尸体进行拍照、摄像的，应当立即予以劝阻，劝阻过程应当全程使用执法记录设备记录。"""),
        LawArticle("第四十三条", "", """交通警察对现场停放的尸体以及敏感的物品要用尸袋、围布等予以遮盖，避免外露。事故现场血腥、惨烈的，可采用立体围挡设施进行遮挡。"""),
        LawArticle("第四十四条", "", """已初步确定肇事逃逸车辆的车型、车号、车身特征或者逃逸路线、方向等信息的，交通警察应当立即报告指挥中心布置堵截和查缉。"""),
        LawArticle("第四十五条", "", """交通警察应当根据现场情况，确认案件性质和管辖权。对不属于本单位管辖区域的，报告指挥中心通知有管辖权的公安机关交通管理部门赶赴现场；管辖权有争议的，报告共同的上一级公安机关交通管理部门指定管辖，上一级机关应当在接到报告后二十四小时内作出决定。"""),
        LawArticle("第四十六条", "", """交通警察应当现场查验道路交通事故当事人的身份证件、机动车驾驶证、机动车行驶证、保险标志等，并进行登记。依法传唤交通肇事嫌疑人。驾驶人不明确的，应当按照《道路交通事故机动车驾驶人识别调查取证规范》等标准调查。"""),
        LawArticle("第四十七条", "", """交通警察在现场勘查过程中，应当使用呼气式酒精测试仪或者唾液试纸等器材，对车辆驾驶人进行酒精含量、国家管制的精神药品和麻醉药品测试。发现饮酒或者服用国家管制的精神药品、麻醉药品嫌疑的，应当及时提取血样或者尿样，及时送交有资质的鉴定机构检验。车辆驾驶人当场死亡或者受伤无法接受测试的，应当及时抽血或者提取尿样。"""),
        LawArticle("第四十八条", "", """提取的血样、尿样一式两份，提取人、被提取人、办案交通警察应当分别在《当事人血样（尿样）提取登记表》上签名，被提取人拒绝签名的，予以注明。交通警察应当使用执法记录设备全程记录血样提取过程。"""),
        LawArticle("第四十九条", "", """交通警察应当按照有关法律法规和《道路交通事故痕迹物证勘验》等标准的规定，客观、全面勘查现场，及时发现、提取痕迹物证，通过照相、摄像、标记、绘图、制作现场勘查笔录等方式固定现场证据。"""),
        LawArticle("第五十条", "", """交通警察应当按照《道路交通事故现场勘验照相》等标准，拍摄、制作道路交通事故照片。事故现场有两辆以上车辆无法识别或者两具以上尸体的，应当编号，逐一拍照。"""),
        LawArticle("第五十一条", "", """交通警察应当按照《道路交通事故现场图绘制》《道路交通事故现场图形符号》等标准，绘制道路交通事故现场记录图或者制作现场实景记录图，并根据需要绘制现场比例图、现场断面图、现场立面图、现场分析图。"""),
        LawArticle("第五十二条", "", """交通警察应当及时制作道路交通事故现场勘查笔录，主要载明：（一）相关部门和人员到达现场时间、勘查开始与结束时间；（二）事故现场具体位置、天气、照明以及道路、设施和周围环境情况；（三）现场监控设备情况；（四）现场伤亡人员基本情况及救援简要过程；（五）现场事故车辆车型、牌号及车辆挡位、转向、灯光、仪表指针位置，行驶记录仪、卫星定位装置等安装使用情况；（六）现场痕迹物证的种类、形态、尺寸、位置以及固定或者提取情况；（七）对车辆驾驶人进行酒精、精神药品、麻醉药品测试及提取血样、尿样情况；（八）肇事车辆不在现场的，初步调查认定的驶离方向、车型、牌号、车身颜色；（九）勘查交通警察认为应当记录的其他情况。"""),
        LawArticle("第五十三条", "", """对需要进一步核查、检验、鉴定的车辆、证件、物品等，交通警察应当依法扣留或者扣押，并出具行政强制措施凭证或者扣押决定书、扣押清单等法律文书，当场送达当事人。"""),
        LawArticle("第五十四条", "", """交通警察在现场勘查过程中，应当注意查找现场证人，记录证人的姓名、家庭住址、联系方式等信息。可以在现场对当事人、证人分别进行询问并制作询问笔录。"""),
        LawArticle("第五十五条", "", """道路交通事故造成人员死亡的，应当经急救、医疗人员确认，并由具备资质的医疗机构出具死亡证明。"""),
        LawArticle("第五十六条", "", """交通警察应当尽快核查道路交通事故当事人身份以及伤亡人员家属联系方式；核查清楚后，应当及时告知伤亡人员家属伤者就医的医疗机构或者尸体的存放单位。"""),
        LawArticle("第五十七条", "", """现场勘查结束后，交通警察应当组织清理事故现场，清点、登记并按规定处理现场遗留物品。通知殡葬服务单位或者有停尸条件的医疗机构将尸体运走存放。"""),
        LawArticle("第五十八条", "", """因条件限制或者案情复杂，现场勘查有困难的，经县级以上公安机关交通管理部门负责人批准，可以保留部分或者全部事故现场，待条件具备后再继续勘查。"""),
        LawArticle("第五十九条", "", """现场勘查结束后，交通警察应当立即赶往医疗机构了解受伤人员伤情、案发经过等情况，并告知医护人员伤情发生变化或者死亡等特殊情况时立即告知公安机关交通管理部门。"""),
        LawArticle("第六十条", "", """交通警察应当在事故现场撤除后二十四小时内，按照《公安机关办理行政案件程序规定》对交通肇事嫌疑人、其他当事人进行询问，及时对证人进行询问，并制作询问笔录。"""),
        LawArticle("第六十一条", "", """道路交通事故有人员受伤并已被送往医疗机构的，交通警察应当尽快赶赴医疗机构了解情况，记录伤者姓名、年龄、性别、受伤部位和程度等情况；必要时对伤者特征通过拍照、录像等方式固定。伤者因伤情严重无法接受询问的，应当记录在案，伤情好转能够接受询问时及时进行询问。"""),
        LawArticle("第六十二条", "", """对犯罪嫌疑人进行讯问，应当按照《公安机关办理刑事案件程序规定》进行。"""),
        LawArticle("第六十三条", "", """办案交通警察应当及时提取《受案登记表》、接处警记录表等接警记录。"""),
        LawArticle("第六十四条", "", """因调查需要，公安机关交通管理部门可以向有关单位、个人调取汽车行驶记录仪、卫星定位装置、技术监控设备的记录资料以及其他与事故有关的证据材料。调取证据应当经办案部门负责人批准，开具调取证据通知书。"""),
        LawArticle("第六十五条", "", """交通警察将当事人的身份证件、驾驶证、行驶证等证据材料复印或者照相、扫描作为证据使用时，应当注明提取的时间、是否与原件一致、原件的来源及存放处，并由制作人和物品持有人签名。"""),
        LawArticle("第六十六条", "", """有关单位或者个人主动提供证据的，不再办理调取手续，但应当出具《接受证据清单》，一式三份。"""),
        LawArticle("第六十七条", "", """交通警察组织辨认前，应当向辨认人详细询问辨认对象的具体特征，查明辨认人是否具备辨认条件。"""),
        LawArticle("第六十八条", "", """被辨认的照片应当按顺序编号，照片中不得出现肇事嫌疑人、陪衬人的姓名等身份信息，不得给予辨认人任何暗示。多次辨认应当对辨认对象重新排序。"""),
        LawArticle("第六十九条", "", """辨认结束后，应当制作辨认笔录，载明辨认的起止时间、地点，办案交通警察、记录人、辨认人、见证人、辨认对象的基本情况，辨认事由、目的、过程、结果，并由相关人员签名。"""),
        LawArticle("第七十条", "", """因调查取证的需要，经县级以上公安机关交通管理部门负责人批准，交通警察可以补充勘查道路交通事故现场或者进行模拟实验。实验的经过和结果应当进行录音、录像并制作实验笔录。模拟实验禁止危险、侮辱人格或者有伤风化的行为。"""),
        LawArticle("第七十一条", "", """对当事人生理、精神状况、人体损伤、尸体、车辆及其行驶速度、痕迹、物品以及现场的道路状况等需要检验、鉴定的，应当按照《道路交通事故处理程序规定》第四十九条规定的时限和要求办理。对交通肇事逃逸案件，应当自查获肇事嫌疑车辆之日起三日内对嫌疑车辆进行检验、鉴定。"""),
        LawArticle("第七十二条", "", """公安机关交通管理部门及其送检人不得暗示或者强迫鉴定机构及其鉴定人作出某种鉴定意见。"""),
        LawArticle("第七十三条", "", """尸体检验报告确定后，应当制作《尸体处理通知书》，通知死者家属在十日内办理丧葬事宜。无正当理由逾期不办理的应当记录在案，经县级以上公安机关或者上一级公安机关交通管理部门负责人批准处理尸体。"""),
        LawArticle("第七十四条", "", """卫生行政主管部门许可的医疗机构具有执业资格的医生出具的诊断证明，公安机关交通管理部门可以作为认定人身伤害程度的依据。但当事人涉嫌交通肇事犯罪、要求做伤情鉴定以及对伤害程度有争议的，应当委托具有资质的专门机构进行伤情鉴定。"""),
        LawArticle("第七十五条", "", """公安机关交通管理部门应当对检验报告、鉴定意见进行审核。经审核具有《道路交通事故处理程序规定》第五十五条第一款规定情形之一的，经县级以上公安机关交通管理部门负责人批准，应当在收到检验报告、鉴定意见之日起三日内重新委托检验、鉴定。"""),
        LawArticle("第七十六条", "", """伤残评定、财产损失评估由当事人自行委托具备资质的机构进行评定、评估。财产损失数额较大涉嫌刑事犯罪的，应当由公安机关交通管理部门委托。"""),
        LawArticle("第七十七条", "", """对身份不明的尸体，办案交通警察应当根据尸体的DNA、手印、体貌特征等信息，通过全国失踪人员信息管理系统及其他信息系统进行查询比对。"""),
        LawArticle("第七十八条", "", """经调查尸体身份无法确定的，应当由法医提取人身识别检材，对尸体拍照、采集信息后，填写《未知名尸体信息登记／撤销表》，自发现未知名尸体之日起十日内通报设区的市公安机关刑侦部门，录入未知名尸体信息系统。"""),
        LawArticle("第七十九条", "", """经调查尸体身份无法确定的，公安机关交通管理部门应当在道路交通事故发生之日起三十日内在设区的市级以上报纸刊登认尸启事。登报后三十日仍无人认领的，经县级以上公安机关负责人或者上一级公安机关交通管理部门负责人批准，可以及时处理尸体。对未知名尸体的骨灰存放一年，存放证留档备查。"""),
        LawArticle("第八十条", "", """设区的市公安机关交通管理部门应当组建专职逃逸案件侦破队伍。县级公安机关交通管理部门应当制作辖区警力部署、急救和医疗机构、修理厂、车辆配件门市部、洗车场、加油站、视频监控点、道路收费站及主要出入口等重要信息分布图。"""),
        LawArticle("第八十一条", "", """发生交通肇事逃逸案件后，公安机关交通管理部门应当立即启动查缉预案，布置警力堵截，并通过全国公安交通集成指挥平台进行查缉布控。"""),
        LawArticle("第八十二条", "", """公安机关交通管理部门应当通过现场勘查、检验鉴定、询问当事人和证人、调取监控录像等，调查交通事故发生时间范围、地点交通环境、肇事逃逸车辆的厂牌型号牌号车身颜色特征损坏部位装载货物逃逸方向、肇事嫌疑人体貌衣着等基本情况，确定查缉方案。"""),
        LawArticle("第八十三条", "", """肇事车辆逃逸的，公安机关交通管理部门可以发布协查通报，请求有关公安机关交通管理部门协助查缉。协查通报应当由事故发生地的县级公安机关交通管理部门向肇事车辆可能逃逸区域的同级机关发布。"""),
        LawArticle("第八十四条", "", """公安机关交通管理部门接到协查通报后，应当立即在肇事逃逸车辆可能通过的路段、路口部署警力严格排查，发现交通肇事逃逸车辆或者嫌疑车辆的应当予以扣留；肇事逃逸车辆为本地车辆的立即组织专人查扣；肇事逃逸嫌疑人为本地人员的依法传唤。"""),
        LawArticle("第八十五条", "", """公安机关交通管理部门侦办交通肇事逃逸案件，应当做好工作记录。造成人员死亡的逃逸案件，应当在不泄露侦办工作秘密的前提下，定期主动向受害人家属通报侦办进展情况。"""),
        LawArticle("第八十六条", "", """公安机关交通管理部门应当建立交通肇事逃逸案件侦破奖励制度，对有功单位和人员及时表彰奖励。"""),
        LawArticle("第八十七条", "", """交通肇事嫌疑人逃逸涉嫌犯罪的，公安机关交通管理部门应当自刑事案件立案之日起一个月内将犯罪嫌疑人信息通过同级公安机关刑侦部门录入全国在逃人员信息系统，抓获犯罪嫌疑人后予以撤销。"""),
        LawArticle("第八十八条", "", """公安机关交通管理部门排查中发现涉嫌交通肇事逃逸的车辆的，应当通知车辆所有人在规定时间内将车辆停放至指定地点接受调查。"""),
        LawArticle("第八十九条", "", """交通警察应当自现场调查之日起七日内，交通肇事逃逸案件自查获交通肇事车辆和驾驶人之日起七日内，需要进行检验、鉴定的自检验、鉴定结论确定之日起二日内，向道路交通事故处理机构负责人提交道路交通事故调查报告。道路交通事故处理机构负责人应当在接到报告之日起二日内进行审批。"""),
        LawArticle("第九十条", "", """对死亡事故和其他疑难、复杂案件，道路交通事故处理机构负责人应当召集具有中级以上道路交通事故处理资格的民警集体研究，按照少数服从多数原则形成集体研究意见，并将不同意见记录在案，提交负责人审批。集体研究和审批工作需在接到调查报告之日起二日内完成。"""),
        LawArticle("第九十一条", "", """道路交通事故调查报告经审批后，办案交通警察应当根据审批意见制作道路交通事故认定书或者道路交通事故证明，并提交公安机关交通管理部门负责人审批。"""),
        LawArticle("第九十二条", "", """发生死亡事故以及复杂、疑难的伤人事故后，公安机关交通管理部门应当在制作道路交通事故认定书或者道路交通事故证明前，召集各方当事人到场，公开调查取得的证据。公开证据应当由二名以上办案交通警察主持，参加证据公开的人员每方不得超过三人。"""),
        LawArticle("第九十三条", "", """当事人及其代理人收到道路交通事故认定书后，要求查阅道路交通事故证据材料的，应当提交书面申请，除涉及国家秘密、商业秘密或者个人隐私以及应证人要求保密的内容外，公安机关交通管理部门应当安排其在指定地点按照规定查阅。"""),
        LawArticle("第九十四条", "", """符合《道路交通事故处理程序规定》第六十八条规定道路交通事故认定的时限中止计算的，公安机关交通管理部门应当制作《道路交通事故认定中止告知书》，告知当事人或者其代理人认定时限中止的原因、依据和时限。"""),
        LawArticle("第九十五条", "", """伤人事故符合《道路交通事故处理程序规定》第六十九条规定情形的，办案交通警察应当告知当事人可以自事故发生之日起三日内申请快速处理。当事人申请快速处理的，经批准可以自申请之日起五日内制作道路交通事故认定书。"""),
        LawArticle("第九十六条", "", """省级和设区的市公安机关交通管理部门应当组织具有道路交通事故处理中级以上资格的交通警察负责道路交通事故认定的复核工作。复核时交通警察不得少于二人。"""),
        LawArticle("第九十七条", "", """当事人及其法定代理人对道路交通事故认定或者出具道路交通事故证明有异议的，可以由本人或者其法定代理人、委托代理人申请复核。委托代理人申请复核的，应当提交授权委托书。"""),
        LawArticle("第九十八条", "", """当事人逾期提交复核申请的，上一级公安机关交通管理部门不予受理，并自收到复核申请之日起三日内书面通知申请人。"""),
        LawArticle("第九十九条", "", """上一级公安机关交通管理部门受理复核申请的，应当自收到复核申请之日起三日内书面通知各方当事人。"""),
        LawArticle("第一百条", "", """上一级公安机关交通管理部门经复核后，应当作出复核结论，载明复核申请人基本情况、申请复核的主要事项理由和依据、复核意见。复核结论应当加盖道路交通事故处理复核专用章，送达各方当事人和原办案单位。"""),
        LawArticle("第一百零一条", "", """公安机关交通管理部门办理复核案件时，可以设立复核委员会。复核委员会实行一案一设，由五至九人组成，成员人数应当为单数。"""),
        LawArticle("第一百零二条", "", """省级和设区的市公安机关交通管理部门可以设立案件复核委员会专业人员库。"""),
        LawArticle("第一百零三条", "", """复核委员会复核案件时应当由办理复核案件的交通警察主持，共同研究形成复核意见，报公安机关交通管理部门负责人审批，批准后以公安机关交通管理部门名义作出复核结论。"""),
        LawArticle("第一百零四条", "", """上一级公安机关交通管理部门作出责令原办案单位重新调查、认定的复核结论的，应当制作《重新调查、认定意见书》。原办案单位应当在规定时限内重新调查、认定，重新制作的道路交通事故认定书或事故证明应当另行编号，并注明撤销原文书。"""),
        LawArticle("第一百零五条", "", """受理复核申请后，任何一方当事人就该事故向人民法院提起诉讼并经受理的，公安机关交通管理部门应当及时将受理复核申请的有关情况书面告知相关人民法院。"""),
        LawArticle("第一百零六条", "", """公安机关交通管理部门应当按照《道路交通安全违法行为处理程序规定》，对当事人的道路交通安全违法行为作出处罚。扣留当事人机动车驾驶证，经调查需要给予暂扣处罚的，扣留一日折抵暂扣期限一日。"""),
        LawArticle("第一百零七条", "", """公安机关交通管理部门扣押机动车驾驶证后，应当及时在公安交通管理综合应用平台将其驾驶证状态标注为扣押状态。发还的应当在发还后二十四小时内解除扣押状态标注。"""),
        LawArticle("第一百零八条", "", """发生道路交通事故构成犯罪，依法应当吊销机动车驾驶证的，公安机关交通管理部门在查询到机动车驾驶人有罪判决信息或者收到有罪判决书、司法建议函后，由设区的市公安机关交通管理部门依法吊销其驾驶证。同时具有饮酒后或者醉酒驾驶机动车、逃逸情形的，还应当依法作出终生不得重新取得机动车驾驶证的决定。"""),
        LawArticle("第一百零九条", "", """专业运输单位的车辆发生一次死亡三人以上的道路交通事故，且该单位或者车辆驾驶人承担全部责任或者主要责任的，事故发生地县级公安机关交通管理部门应当将肇事情况录入综合应用平台并转递至单位所在地。对六个月内两次发生一次死亡三人以上事故且负全责或主责的，经批准可以责令限期消除安全隐患，禁止未消除隐患的机动车上道路行驶。"""),
        LawArticle("第一百一十条", "", """道路交通事故各方当事人一致请求公安机关交通管理部门调解的，应当在收到事故认定书、事故证明或者复核结论之日起十日内提出，或者自人民调解委员会终止调解之日起三日内提出。符合规定的应予受理。"""),
        LawArticle("第一百一十一条", "", """调解开始前，交通警察应当对调解参加人的资格进行审核，包括当事人或其代理人、车辆所有人或管理人、保险公司人员、救助基金管理机构人员等。对不具备资格的应当告知更换或退出。"""),
        LawArticle("第一百一十二条", "", """同一起道路交通事故中当事人为三方以上的，交通警察可以根据赔偿权利人和义务人的共同申请，分别组织调解。"""),
        LawArticle("第一百一十三条", "", """交通警察应当按照《道路交通事故处理程序规定》第九十一条的有关规定主持调解，并制作调解记录，记录调解过程及当事人提出的意见。"""),
        LawArticle("第一百一十四条", "", """道路交通事故造成人身伤亡的，交通警察应当按照《民法典》侵权责任编及最高人民法院相关司法解释，按照事故发生地省级政府统计部门公布的上一年度相关统计数据，计算伤亡人员损害赔偿的项目和数额。"""),
        LawArticle("第一百一十五条", "", """道路交通事故造成伤亡人员的损害赔偿数额、财产损失以及其他损失确定后，交通警察可以根据事故认定书确定的当事各方过错大小，提出各方承担赔偿责任的比例和数额建议，由赔偿权利人和义务人协商；协商不成的再进行调解。"""),
        LawArticle("第一百一十六条", "", """经调解达成协议的，应当当场制作《道路交通事故损害赔偿调解书》，由参加调解的各方当事人签字，主持调解的交通警察签名或盖章并加盖道路交通事故处理专用章，分别送达各方当事人。经调解未达成协议的，应当制作《道路交通事故损害赔偿调解终结书》。"""),
        LawArticle("第一百一十七条", "", """对未知名死者的人身损害赔偿，公安机关交通管理部门应当将其所得赔偿费交付有关部门保存，其损害赔偿权利人确认后，通知有关部门交付损害赔偿权利人。"""),
        LawArticle("第一百一十八条", "", """公安机关交通管理部门应当协助道路交通事故社会救助基金管理机构做好救助基金垫付费用的追偿工作。"""),
        LawArticle("第一百一十九条", "", """具有《道路交通事故处理程序规定》第九十七条规定第一、三项情形的，公安机关交通管理部门可以按照有关规定办理边控手续，依法不准其出境。"""),
        LawArticle("第一百二十条", "", """公安机关交通管理部门在办理道路交通事故案件过程中，有下列情形之一的应当予以结案：（一）事故认定书、事故证明生效后，已对违法行为人行政处罚完毕，且当事人提起民事诉讼或者损害赔偿经调解达成协议、调解终结、终止调解，以及在规定期限内未提出调解申请或申请不予受理的；（二）当事人涉嫌交通肇事犯罪，案件已经人民法院判决或者检察机关不起诉决定生效，且行政处罚完毕的；（三）其他应当结案的情形。未侦破的交通肇事逃逸案件应当继续侦办，不得结案。"""),
        LawArticle("第一百二十一条", "", """公安机关交通管理部门应当按照《道路交通事故案卷文书》标准制作道路交通事故案卷，建立道路交通事故档案。道路交通事故案卷应当在结案后三十日内移交、归档。"""),
        LawArticle("第一百二十二条", "", """适用一般程序处理的道路交通事故案卷分正卷、副卷，一案一档。同一起道路交通事故中涉及多人被追究法律责任的，不再分别立卷建档。适用简易程序处理的，可以多案一卷，定期归档，间隔期限最长不得超过三个月。"""),
        LawArticle("第一百二十三条", "", """公安机关交通管理部门应当妥善保管道路交通事故案卷材料，非经法定审批程序不得销毁。对损毁、丢失以及伪造或者擅自修改、抽取案卷材料的，应当依照《档案法》给予行政处分；构成犯罪的依法追究刑事责任。"""),
        LawArticle("第一百二十四条", "", """公安机关交通管理部门应当建立、完善道路交通事故档案的借阅、查阅、复印、翻拍、调用、销毁以及安全管理制度。"""),
        LawArticle("第一百二十五条", "", """人民法院、人民检察院审理、审查道路交通事故案件需要调取案卷的，公安机关交通管理部门应当按照规定时间将道路交通事故正卷移交，并复制正卷形成副本。当事人及其代理人查阅案卷材料的，应当将查阅申请与道路交通事故副卷一并存档。"""),
        LawArticle("第一百二十六条", "", """公安机关交通管理部门应当加强道路交通事故处理执法监督管理，建立健全本单位及所属交通警察执法档案，实施执法质量考核评议、执法责任制和执法过错责任追究。"""),
        LawArticle("第一百二十七条", "", """上级公安机关交通管理部门对下一级机关应当定期开展道路交通事故案卷评查，省级公安机关交通管理部门每年度至少组织开展一次。"""),
        LawArticle("第一百二十八条", "", """交通警察在事故处理中，因故意或者过失造成重要证据灭失、违法扣留扣押物品、违法采取强制措施、错误采取刑事强制措施、违规收取费用、采用逼供骗供诱供、制作笔录弄虚作假、拒绝或拖延履行法定职责、错误立案或出具虚假文书、丢失案卷等执法错误的，应当依据《公安机关人民警察执法过错责任追究规定》追究执法过错责任。"""),
        LawArticle("第一百二十九条", "", """具有下列情形之一的，上级公安机关交通管理部门可以对原办案单位作出的事故认定书、事故证明予以撤销或者变更：（一）原办案单位拒不执行复核结论的；（二）经复核责令重新调查认定，原办案单位未重新调查就以原有事实证据理由作出相同或相近认定的；（三）重新作出事故认定后仍存在事实不清、主要证据不足、适用法律错误、责任划分不公正、违反法定程序的；（四）其他依法应当撤销或变更的情形。"""),
        LawArticle("第一百三十条", "", """本规范中下列用语的含义：（一）本规范所称的"二日""三日""五日""七日""十日"是指工作日，不包括节假日。（二）本规范所称的"以上""以下"均包括本数在内。"""),
        LawArticle("第一百三十一条", "", """本规范自2018年5月1日起施行，公安部印发的《道路交通事故处理工作规范》（公交管〔2008〕277号）同时废止。法律、行政法规以及公安部规章另有规定的，以法律、行政法规、规章为准。此前公安部发布的其他文件规定与本规范不一致的，以本规范为准。"""),
    )
)
